        void RunBlockStandardChecks<TInvoker, TScalar>(TInvoker inv, TScalar scalarInv, CheckFlags flags)
            where TInvoker : struct, IfloatBlockSolverInvoker
            where TScalar : struct, IfloatSquareSolverInvoker
        {
            for (int i = 0; i < DenseCount; i++)
            {
                var gm = (GalleryDenseMatrix)i;
                if (flags.SkipTinyDense && IsTinyDense(gm)) continue;
                if (MatrixProfileMatch.Applicable(inv.Requires, inv.Forbids, GalleryProfiles.Of(gm)))
                    CheckDense(inv, scalarInv, gm, flags);
            }

            for (int i = 0; i < BSRCount; i++)
            {
                var gm = (GalleryBSRMatrix)i;
                if (MatrixProfileMatch.Applicable(inv.Requires, inv.Forbids, GalleryProfiles.Of(gm)))
                    CheckBSR(inv, scalarInv, gm, flags);
            }
        }

        // Checks #1-4 (converges/correctness/determinism/identity-fold, block-shaped) plus #6-9 on
        // one dense literature-gallery matrix. Branches on NeedsGeneralDenseOperator to pick the
        // correct TOp at compile time (SS4's landmine) before handing off to the shared core.
        void CheckDense<TInvoker, TScalar>(TInvoker inv, TScalar scalarInv, GalleryDenseMatrix gm, CheckFlags flags)
            where TInvoker : struct, IfloatBlockSolverInvoker
            where TScalar : struct, IfloatSquareSolverInvoker
        {
            if (inv.NeedsGeneralDenseOperator)
            {
                var arena = new Arena(Allocator.Persistent);
                var A = floatKrylovBatteryGallery.Build(ref arena, gm);
                CheckDenseCore(inv, scalarInv, gm, ref arena, in A, new floatDenseOperatorGeneral(in A), flags);
            }
            else
            {
                var arena = new Arena(Allocator.Persistent);
                var A = floatKrylovBatteryGallery.Build(ref arena, gm);
                CheckDenseCore(inv, scalarInv, gm, ref arena, in A, new floatDenseOperator(in A), flags);
            }
        }

        void CheckDenseCore<TInvoker, TScalar, TOp>(TInvoker inv, TScalar scalarInv, GalleryDenseMatrix gm,
                                                     ref Arena arena, in floatMxN A, in TOp Aop, CheckFlags flags)
            where TInvoker : struct, IfloatBlockSolverInvoker
            where TScalar : struct, IfloatSquareSolverInvoker
            where TOp : struct, IfloatLinearOperator
        {
            int n = A.M_Rows;
            MatrixProfile tags = GalleryProfiles.Of(gm);
            float tolBand = TolBand(tags);

            var B = arena.floatRandomMat(flags.S, n, (float)(-1), (float)1, 0xD100u + (uint)gm);

            inv.Init(ref arena, n, flags.S);
            scalarInv.Init(ref arena, n);

            // 1. Converges: Solved or MaxIterations, AND the fresh (recomputed) residual bound holds.
            var X1 = arena.floatMat(flags.S, n);
            BlockSolveInfo info1 = inv.Solve(in Aop, in B, ref X1);
            bool statusOk1 = info1.status == IterativeSolveStatus.Converged || info1.status == IterativeSolveStatus.MaxIterations;
            Record(statusOk1, (int)gm, 1, (float)(int)info1.status, (float)0);
            float relRes1 = floatKrylovBatteryOracles.RelResidualBlockDense(in A, in X1, in B);
            Record(relRes1 <= (float)10 * inv.Tol, (int)gm, 1, relRes1, (float)10 * inv.Tol);
            VerifyHonestBlockOp(info1.status, in Aop, in X1, in B, flags.S, n, inv.Tol, (int)gm);

            // 2. Correctness vs. direct-solve reference, per column (same A, B, and the X1 solved in #1).
            for (int j = 0; j < flags.S; j++)
            {
                var bj = floatKrylovBatteryOracles.Row(ref arena, in B, j, n);
                var xRefj = ReferenceSolveDense(in A, in bj, tags);
                for (int c = 0; c < n; c++)
                    Record(math.abs(X1[j, c] - xRefj[c]) <= tolBand * ((float)1 + math.abs(xRefj[c])), (int)gm, 2, X1[j, c], xRefj[c]);
            }

            // 3. Determinism: two independent solves from X0=0 on the identical (A, B) match bit-for-bit.
            var X3a = arena.floatMat(flags.S, n);
            var X3b = arena.floatMat(flags.S, n);
            BlockSolveInfo info3a = inv.Solve(in Aop, in B, ref X3a);
            BlockSolveInfo info3b = inv.Solve(in Aop, in B, ref X3b);
            for (int j = 0; j < flags.S; j++)
                for (int c = 0; c < n; c++)
                    Record(X3a[j, c] == X3b[j, c], (int)gm, 3, X3a[j, c], X3b[j, c]);
            Record(info3a.iterations == info3b.iterations, (int)gm, 3, (float)info3a.iterations, (float)info3b.iterations);
            VerifyHonestBlockOp(info3a.status, in Aop, in X3a, in B, flags.S, n, inv.Tol, (int)gm);
            VerifyHonestBlockOp(info3b.status, in Aop, in X3b, in B, flags.S, n, inv.Tol, (int)gm);

            // 4. Identity-fold: the unpreconditioned path == the generic path with an explicit identity.
            var X4a = arena.floatMat(flags.S, n);
            var X4b = arena.floatMat(flags.S, n);
            BlockSolveInfo info4a = inv.Solve(in Aop, in B, ref X4a);
            BlockSolveInfo info4b = inv.SolveWithPrecond(in Aop, default(floatIdentityPreconditioner), in B, ref X4b);
            for (int j = 0; j < flags.S; j++)
                for (int c = 0; c < n; c++)
                    Record(X4a[j, c] == X4b[j, c], (int)gm, 4, X4a[j, c], X4b[j, c]);
            Record(info4a.iterations == info4b.iterations, (int)gm, 4, (float)info4a.iterations, (float)info4b.iterations);
            VerifyHonestBlockOp(info4a.status, in Aop, in X4a, in B, flags.S, n, inv.Tol, (int)gm);
            VerifyHonestBlockOp(info4b.status, in Aop, in X4b, in B, flags.S, n, inv.Tol, (int)gm);

            // 13. Dense non-diagonal SPD preconditioner (SPD block-CG solvers only). Check #5 exercises
            // the preconditioned path with a BLOCK-DIAGONAL (block-Jacobi) M over BSR; a fully-coupled
            // dense SPD M is the regression guard for a recurrence that mishandles M's off-diagonal
            // coupling (the V-space-vs-r-space class of bug that gated block MINRES). Any SPD M keeps
            // preconditioned block-CG converging to the SAME solution, so this asserts Converged/
            // MaxIterations, a small fresh residual, and per-column agreement with the direct oracle.
            // Restricted to well-conditioned SPD dense entries so a correct solver converges cleanly.
            if (flags.DensePrecondSPD && (tags & MatrixProfile.SPD) != 0 && (tags & MatrixProfile.IllConditioned) == 0)
            {
                var M13 = new BlockSpdPre { Nmat = BuildDenseSpdPre(ref arena, n, 0xD500u + (uint)gm) };
                var X13 = arena.floatMat(flags.S, n);
                BlockSolveInfo info13 = inv.SolveWithPrecond(in Aop, in M13, in B, ref X13);
                bool statusOk13 = info13.status == IterativeSolveStatus.Converged || info13.status == IterativeSolveStatus.MaxIterations;
                Record(statusOk13, (int)gm, 13, (float)(int)info13.status, (float)0);
                float relRes13 = floatKrylovBatteryOracles.RelResidualBlockDense(in A, in X13, in B);
                Record(relRes13 <= (float)10 * inv.Tol, (int)gm, 13, relRes13, (float)10 * inv.Tol);
                for (int j = 0; j < flags.S; j++)
                {
                    var bj = floatKrylovBatteryOracles.Row(ref arena, in B, j, n);
                    var xRefj = ReferenceSolveDense(in A, in bj, tags);
                    for (int c = 0; c < n; c++)
                        Record(math.abs(X13[j, c] - xRefj[c]) <= tolBand * ((float)1 + math.abs(xRefj[c])), (int)gm, 13, X13[j, c], xRefj[c]);
                }
                VerifyHonestBlockOp(info13.status, in Aop, in X13, in B, flags.S, n, inv.Tol, (int)gm);
            }

            CheckBlockAdditions(inv, scalarInv, ref arena, in Aop, n, tags, (int)gm, 0xD800u + (uint)gm, flags);

            arena.Dispose();
        }

        // Checks #1-5 (adds Sparse-only preconditioned convergence) plus #6-9 on one BSR gallery
        // matrix -- floatBSROperator.ApplyBlock (BSR.spMM) has no symmetric-only shortcut, so no
        // NeedsGeneralDenseOperator branch is needed here (SS4).
        void CheckBSR<TInvoker, TScalar>(TInvoker inv, TScalar scalarInv, GalleryBSRMatrix gm, CheckFlags flags)
            where TInvoker : struct, IfloatBlockSolverInvoker
            where TScalar : struct, IfloatSquareSolverInvoker
        {
            var arena = new Arena(Allocator.Persistent);

            var A = floatKrylovBatteryGallery.Build(ref arena, gm);
            int n = A.M_Rows;
            var Aop = new floatBSROperator(in A);
            MatrixProfile tags = GalleryProfiles.Of(gm);
            float tolBand = TolBand(tags);

            var B = arena.floatRandomMat(flags.S, n, (float)(-1), (float)1, 0xB100u + (uint)gm);

            inv.Init(ref arena, n, flags.S);
            scalarInv.Init(ref arena, n);

            // 1. Converges.
            var X1 = arena.floatMat(flags.S, n);
            BlockSolveInfo info1 = inv.Solve(in Aop, in B, ref X1);
            bool statusOk1 = info1.status == IterativeSolveStatus.Converged || info1.status == IterativeSolveStatus.MaxIterations;
            Record(statusOk1, (int)gm, 1, (float)(int)info1.status, (float)0);
            float relRes1 = floatKrylovBatteryOracles.RelResidualBlockBSR(in A, in X1, in B);
            Record(relRes1 <= (float)10 * inv.Tol, (int)gm, 1, relRes1, (float)10 * inv.Tol);
            VerifyHonestBlockOp(info1.status, in Aop, in X1, in B, flags.S, n, inv.Tol, (int)gm);

            // 2. Correctness vs. direct-solve reference (densify A -- no direct BSR factorization).
            var Adense = A.ToDense(ref arena);
            for (int j = 0; j < flags.S; j++)
            {
                var bj = floatKrylovBatteryOracles.Row(ref arena, in B, j, n);
                var xRefj = ReferenceSolveDense(in Adense, in bj, tags);
                for (int c = 0; c < n; c++)
                    Record(math.abs(X1[j, c] - xRefj[c]) <= tolBand * ((float)1 + math.abs(xRefj[c])), (int)gm, 2, X1[j, c], xRefj[c]);
            }

            // 3. Determinism.
            var X3a = arena.floatMat(flags.S, n);
            var X3b = arena.floatMat(flags.S, n);
            BlockSolveInfo info3a = inv.Solve(in Aop, in B, ref X3a);
            BlockSolveInfo info3b = inv.Solve(in Aop, in B, ref X3b);
            for (int j = 0; j < flags.S; j++)
                for (int c = 0; c < n; c++)
                    Record(X3a[j, c] == X3b[j, c], (int)gm, 3, X3a[j, c], X3b[j, c]);
            Record(info3a.iterations == info3b.iterations, (int)gm, 3, (float)info3a.iterations, (float)info3b.iterations);
            VerifyHonestBlockOp(info3a.status, in Aop, in X3a, in B, flags.S, n, inv.Tol, (int)gm);
            VerifyHonestBlockOp(info3b.status, in Aop, in X3b, in B, flags.S, n, inv.Tol, (int)gm);

            // 4. Identity-fold.
            var X4a = arena.floatMat(flags.S, n);
            var X4b = arena.floatMat(flags.S, n);
            BlockSolveInfo info4a = inv.Solve(in Aop, in B, ref X4a);
            BlockSolveInfo info4b = inv.SolveWithPrecond(in Aop, default(floatIdentityPreconditioner), in B, ref X4b);
            for (int j = 0; j < flags.S; j++)
                for (int c = 0; c < n; c++)
                    Record(X4a[j, c] == X4b[j, c], (int)gm, 4, X4a[j, c], X4b[j, c]);
            Record(info4a.iterations == info4b.iterations, (int)gm, 4, (float)info4a.iterations, (float)info4b.iterations);
            VerifyHonestBlockOp(info4a.status, in Aop, in X4a, in B, flags.S, n, inv.Tol, (int)gm);
            VerifyHonestBlockOp(info4b.status, in Aop, in X4b, in B, flags.S, n, inv.Tol, (int)gm);

            // 5. Preconditioned convergence (Sparse-only), M built per inv.PrecondKind. PrecondKind
            // == None (bminres) falls through to the plain unpreconditioned solve, same as the
            // square battery's own else branch -- never constructs a real M for a solver whose
            // preconditioned path is gated off.
            var X5 = arena.floatMat(flags.S, n);
            BlockSolveInfo info5;
            if (inv.PrecondKind == PreconditionerKind.SymmetricBSR)
            {
                var M = arena.floatBlockJacobi(in A);
                info5 = inv.SolveWithPrecond(in Aop, in M, in B, ref X5);
            }
            else if (inv.PrecondKind == PreconditionerKind.NonsymmetricBSR)
            {
                var M = arena.floatILU0(in A);
                info5 = inv.SolveWithPrecond(in Aop, in M, in B, ref X5);
            }
            else
            {
                info5 = inv.Solve(in Aop, in B, ref X5);
            }
            bool statusOk5 = info5.status == IterativeSolveStatus.Converged || info5.status == IterativeSolveStatus.MaxIterations;
            Record(statusOk5, (int)gm, 5, (float)(int)info5.status, (float)0);
            float relRes5 = floatKrylovBatteryOracles.RelResidualBlockBSR(in A, in X5, in B);
            Record(relRes5 <= (float)10 * inv.Tol, (int)gm, 5, relRes5, (float)10 * inv.Tol);
            VerifyHonestBlockOp(info5.status, in Aop, in X5, in B, flags.S, n, inv.Tol, (int)gm);

            CheckBlockAdditions(inv, scalarInv, ref arena, in Aop, n, tags, (int)gm, 0xB800u + (uint)gm, flags);

            arena.Dispose();
        }

        // Block-family additions (shared by CheckDenseCore/CheckBSR, any TOp):
        //   6. Per-column matches scalar (unconditional).
        //   7. Block advantage: block iterations <= worst per-column scalar iterations (gated by
        //      flags.BlockAdvantage -- see Execute()'s BbiCGStab/Bgmres cases).
        //   8. Identical-RHS-columns invariant (forced B[S-1] == B[0]; tolerance-bounded, not
        //      bit-identical -- mirrors BlockCGTests' RankDeficientBlockDeflates precedent). Gated by
        //      flags.IdenticalColumns -- see Execute()'s Bminres case.
        //   9. Rank-deficient RHS graceful: finite output (unconditional) and status never Breakdown
        //      (gated by flags.NoBreakdown -- see Execute()'s Bminres/BbiCGStab cases).
        //  10. Warm-start correctness: a NONZERO initial guess must be carried into the solution, not
        //      discarded -- known X*, B = A X* (Aop.ApplyBlock, correct for the already-selected TOp),
        //      X seeded to a fixed nonzero block unrelated to X*. Applies unconditionally: every
        //      block solver takes ref X.
        //  11. Degenerate/zero-RHS-row: one all-zero row among ordinary rows must not break the whole
        //      batch (generalizes the fixed btfqmr zero-row bug). Status must not report Breakdown
        //      (gated by flags.NoBreakdown, same rationale as check #9), every ordinary row still
        //      reaches its true solution, and the zero row's own output stays at (numerically) zero
        //      -- its exact solution, A being nonsingular.
        void CheckBlockAdditions<TInvoker, TScalar, TOp>(TInvoker inv, TScalar scalarInv, ref Arena arena, in TOp Aop,
                                                           int n, MatrixProfile tags, int gmIdx, uint seedBase, CheckFlags flags)
            where TInvoker : struct, IfloatBlockSolverInvoker
            where TScalar : struct, IfloatSquareSolverInvoker
            where TOp : struct, IfloatLinearOperator
        {
            float tolBand = TolBand(tags);

            // 6/7.
            var B6 = arena.floatRandomMat(flags.S, n, (float)(-1), (float)1, seedBase + 1u);
            var X6 = arena.floatMat(flags.S, n);
            BlockSolveInfo info6 = inv.Solve(in Aop, in B6, ref X6);
            int worstScalarIter = 0;
            for (int j = 0; j < flags.S; j++)
            {
                var bj = floatKrylovBatteryOracles.Row(ref arena, in B6, j, n);
                var xj = arena.floatVec(n);
                SolveInfo infoScalar = scalarInv.Solve(in Aop, in bj, ref xj);
                if (infoScalar.iterations > worstScalarIter) worstScalarIter = infoScalar.iterations;
                for (int c = 0; c < n; c++)
                    Record(math.abs(X6[j, c] - xj[c]) <= tolBand * ((float)1 + math.abs(xj[c])), gmIdx, 6, X6[j, c], xj[c]);
            }
            if (flags.BlockAdvantage)
                Record(info6.iterations <= worstScalarIter, gmIdx, 7, (float)info6.iterations, (float)worstScalarIter);
            VerifyHonestBlockOp(info6.status, in Aop, in X6, in B6, flags.S, n, inv.Tol, gmIdx);

            // 8/9: force two distinct rows (0 and S-1) bit-identical.
            int dupA = 0, dupB = flags.S - 1;
            var B8 = arena.floatRandomMat(flags.S, n, (float)(-1), (float)1, seedBase + 2u);
            for (int c = 0; c < n; c++) B8[dupB, c] = B8[dupA, c];
            var X8 = arena.floatMat(flags.S, n);
            BlockSolveInfo info8 = inv.Solve(in Aop, in B8, ref X8);

            bool anyBad = false;
            for (int j = 0; j < flags.S; j++)
                for (int c = 0; c < n; c++)
                    if (math.isnan(X8[j, c]) || math.isinf(X8[j, c])) anyBad = true;
            Record(!anyBad, gmIdx, 9, anyBad ? (float)1 : (float)0, (float)0);

            if (flags.NoBreakdown)
            {
                bool statusOk9 = info8.status == IterativeSolveStatus.Converged || info8.status == IterativeSolveStatus.MaxIterations;
                Record(statusOk9, gmIdx, 9, (float)(int)info8.status, (float)0);
            }

            if (flags.IdenticalColumns)
                for (int c = 0; c < n; c++)
                    Record(math.abs(X8[dupA, c] - X8[dupB, c]) <= tolBand * ((float)1 + math.abs(X8[dupA, c])), gmIdx, 8, X8[dupA, c], X8[dupB, c]);
            VerifyHonestBlockOp(info8.status, in Aop, in X8, in B8, flags.S, n, inv.Tol, gmIdx);

            // 10. Warm-start correctness.
            var Xstar10 = arena.floatRandomMat(flags.S, n, (float)(-1), (float)1, seedBase + 3u);
            var Bwarm10 = arena.floatMat(flags.S, n);
            Aop.ApplyBlock(in Xstar10, ref Bwarm10, flags.S);
            var Xwarm10 = arena.floatRandomMat(flags.S, n, (float)(-1), (float)1, seedBase + 4u);
            BlockSolveInfo infoWarm10 = inv.Solve(in Aop, in Bwarm10, ref Xwarm10);
            Record(infoWarm10.status == IterativeSolveStatus.Converged, gmIdx, 10, (float)(int)infoWarm10.status, (float)(int)IterativeSolveStatus.Converged);
            float relResWarm10 = floatKrylovBatteryOracles.RelResidualBlockOp(in Aop, in Xwarm10, in Bwarm10, flags.S, n);
            Record(relResWarm10 <= (float)100 * inv.Tol, gmIdx, 10, relResWarm10, (float)100 * inv.Tol);
            VerifyHonestBlockOp(infoWarm10.status, in Aop, in Xwarm10, in Bwarm10, flags.S, n, inv.Tol, gmIdx);

            // 11. Degenerate/zero-RHS-row.
            int zeroRow11 = 0;
            var Bz11 = arena.floatRandomMat(flags.S, n, (float)(-1), (float)1, seedBase + 5u);
            for (int c = 0; c < n; c++) Bz11[zeroRow11, c] = (float)0;
            var Xz11 = arena.floatMat(flags.S, n);
            BlockSolveInfo infoZ11 = inv.Solve(in Aop, in Bz11, ref Xz11);

            if (flags.NoBreakdown)
                Record(infoZ11.status != IterativeSolveStatus.Breakdown, gmIdx, 11, (float)(int)infoZ11.status, (float)(int)IterativeSolveStatus.Breakdown);

            for (int c = 0; c < n; c++)
                Record(math.abs(Xz11[zeroRow11, c]) <= tolBand, gmIdx, 11, Xz11[zeroRow11, c], (float)0);

            if (infoZ11.status != IterativeSolveStatus.Breakdown)
            {
                var scratch11 = arena.floatVec(n);
                for (int j = 0; j < flags.S; j++)
                {
                    if (j == zeroRow11) continue;
                    var bj = floatKrylovBatteryOracles.Row(ref arena, in Bz11, j, n);
                    var xj = floatKrylovBatteryOracles.Row(ref arena, in Xz11, j, n);
                    Aop.Apply(in xj, ref scratch11);
                    float num11 = 0, den11 = 0;
                    for (int c = 0; c < n; c++) { float d = scratch11[c] - bj[c]; num11 += d * d; den11 += bj[c] * bj[c]; }
                    float relRes11 = math.sqrt(num11) / math.sqrt(math.max(den11, (float)1e-30));
                    Record(relRes11 <= (float)100 * inv.Tol, gmIdx, 11, relRes11, (float)100 * inv.Tol);
                }
            }
        }

        // 12. Verify-at-exit honesty (universal invariant, folded into every solve call above rather
        // than a standalone check block): whenever a solve claims Converged, the fresh true residual
        // (recomputed via the caller-supplied TOp, independent of whatever the solver tracked
        // internally) must actually be within a generous bound. Guards the whole silent-false-
        // Converged family across every check site in the loop, not only the "Converges" check.
        void VerifyHonestBlockOp<TOp>(IterativeSolveStatus status, in TOp Aop, in floatMxN X, in floatMxN B,
                                       int s, int n, float tol, int gmIdx)
            where TOp : struct, IfloatLinearOperator
        {
            if (status != IterativeSolveStatus.Converged) return;
            float relRes = floatKrylovBatteryOracles.RelResidualBlockOp(in Aop, in X, in B, s, n);
            Record(relRes <= (float)100 * tol, gmIdx, 12, relRes, (float)100 * tol);
        }

        // Reference solution via the library's own direct solver for A's KIND: CHO for SPD, LU for
        // SymmetricIndefinite/Nonsymmetric.
        floatN ReferenceSolveDense(in floatMxN A, in floatN b, MatrixProfile tags)
        {
            var xRef = b.Copy();
            if ((tags & MatrixProfile.SPD) != 0)
            {
                var L = A.Copy();
                CHO.decompInPlace(ref L);
                CHO.decompSolve(ref L, ref xRef);
            }
            else
            {
                var LUm = A.Copy();
                var P = new Pivot(A.M_Rows, Allocator.Temp);
                LU.decompInPlace(ref LUm, ref P);
                LU.decompSolve(ref LUm, in P, ref xRef);
                P.Dispose();
            }
            return xRef;
        }

        // WellConditioned -> 50*sqrtEps, IllConditioned -> 5E-2 (mirrors KrylovSquareBatteryTests'
        // own bands).
        static float TolBand(MatrixProfile tags)
            => (tags & MatrixProfile.IllConditioned) != 0 ? (float)5E-2 : (float)50 * Consts.floatSqrtEps;

        void Record(bool ok, int matrixIdx, int checkId, float got, float expected)
        {
            if (!ok && Fail[0] == (float)0)
            {
                Fail[0] = (float)1;
                Fail[1] = (float)matrixIdx;
                Fail[2] = (float)checkId;
                Fail[3] = got;
                Fail[4] = expected;
            }
            Assert.IsTrue(ok);
        }
    }

    static Array GetKinds() => Enum.GetValues(typeof(TestJob.SolverKind));

    // Generous timeout: the first case run in a session pays one cold Burst compile of the whole
    // Execute() body, and checks #10/#11/#12 add two more full block solves (plus per-solve honesty
    // re-verification) per gallery matrix on top of checks #1-9 (mirrors KrylovLstsqBatteryTests'
    // own [Timeout], see DEVLOG).
    [Timeout(600000)]
    [TestCaseSource(nameof(GetKinds))]
    public void BlockBattery(TestJob.SolverKind kind)
    {
        var fail = new NativeArray<float>(5, Allocator.TempJob);
        try
        {
            new TestJob { Kind = kind, Fail = fail }.Run();
            if (fail[0] != (float)0)
                Assert.Fail($"{kind}: matrix={fail[1]} check={fail[2]} got={fail[3]} expected={fail[4]}");
        }
        finally { fail.Dispose(); }
    }
}
